/**
 * One open connection to a PostgreSQL server. The connection itself can be
 * replaced (Reconnect), so the app's tabs keep the same session object.
 */
public protocol DatabaseSessionProtocol: AnyObject, Sendable {
    
    /**
     * Applies all changes, or none of them. The statements run in one DO
     * block, sent as one message: PostgreSQL runs it in one implicit
     * transaction. An UPDATE or DELETE that finds no row (someone else
     * changed or deleted it) raises an error, so nothing is applied.
     */
    func commit(changes: PendingChanges, relation: Relation, columns: [Column], primaryKey: [String]) async throws 
    
    /**
     * Inserts the new rows atomically. See [`DatabaseSession::commit`].
     */
    func insert(rows: [NewRow], relation: Relation, columns: [Column]) async throws 
    
    /**
     * Reads the catalog for autocomplete: every relation with its columns,
     * the functions, the schemas and the search path.
     */
    func completer() async throws  -> Completer
    
    /**
     * Writes the rows to `path` and returns how many it wrote. The rows go
     * from the server to the file in a stream, so a large table doesn't
     * fill memory. CSV comes from PostgreSQL's own COPY; JSON from
     * row_to_json, so numbers, booleans and json stay typed.
     */
    func exportRows(relation: Relation, columns: [Column], filters: [RowFilter], sort: RowSort?, primaryKey: [String], scope: ExportScope, format: ExportFormat, path: String) async throws  -> UInt64
    
    /**
     * The rows with these primary keys, whole: the grid cuts long values,
     * and a copy must not. Rows come back in the order of `keys`; a key
     * that no longer matches a row is left out.
     */
    func fullRows(relation: Relation, columns: [Column], primaryKey: [String], keys: [[String]]) async throws  -> [[String?]]
    
    /**
     * Asks the server to stop the statement running on this connection.
