/**
 * A value for a cell. For a new row, a column with no draft gets its DEFAULT.
 */

public enum CellDraft: Equatable, Hashable {
    
    /**
     * Typed text; always sent as a quoted literal, never as SQL.
     */
    case value(text: String
    )
    case null
    /**
     * The column's DEFAULT expression.
     */
    case `default`
    /**
     * One of a fixed set of SQL functions, from the cell menu.
     */
    case function(function: SqlFunction
    )





}

#if compiler(>=6)
extension CellDraft: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCellDraft: FfiConverterRustBuffer {
    typealias SwiftType = CellDraft

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CellDraft {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .value(text: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .null
        
        case 3: return .`default`
        
        case 4: return .function(function: try FfiConverterTypeSqlFunction.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CellDraft, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .value(text):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(text, into: &buf)
            
        
        case .null:
            writeInt(&buf, Int32(2))
        
        
        case .`default`:
            writeInt(&buf, Int32(3))
        
        
        case let .function(function):
            writeInt(&buf, Int32(4))
            FfiConverterTypeSqlFunction.write(function, into: &buf)
            
        }
    }
}


