/**
 * A failure with a message fit to show the user.
 */
public 
enum DatabaseError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Failed(message: String, detail: String?, hint: String?, 
        /**
         * 1-based character offset into the SQL the user ran, when the
         * server reports one.
         */position: UInt32?
    )
    /**
     * The SSH server's key is neither in ~/.ssh/known_hosts nor trusted
     * yet. The app asks the user to trust `fingerprint`, then connects with
     * it as `trusted_fingerprint`.
     */
    case UnknownHostKey(host: String, fingerprint: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension DatabaseError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDatabaseError: FfiConverterRustBuffer {
    typealias SwiftType = DatabaseError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DatabaseError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Failed(
            message: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterOptionString.read(from: &buf), 
            hint: try FfiConverterOptionString.read(from: &buf), 
            position: try FfiConverterOptionUInt32.read(from: &buf)
            )
        case 2: return .UnknownHostKey(
            host: try FfiConverterString.read(from: &buf), 
            fingerprint: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DatabaseError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Failed(message,detail,hint,position):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            FfiConverterOptionString.write(detail, into: &buf)
            FfiConverterOptionString.write(hint, into: &buf)
            FfiConverterOptionUInt32.write(position, into: &buf)
            
        
        case let .UnknownHostKey(host,fingerprint):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(host, into: &buf)
            FfiConverterString.write(fingerprint, into: &buf)
            
        }
    }
}


