    case notEquals
    case contains
    case notContains
    case startsWith
    case endsWith
    case greaterThan
    case greaterOrEqual
    case lessThan
    case lessOrEqual
    /**
     * Comma-separated values.
     */
    case `in`
    case notIn
    /**
     * The value is a LIKE pattern as typed: % and _ are wildcards.
     */
    case like
    case isNull
    case isNotNull





}

